//! Named API-key providers of the Python reference whose requests need no special handling.
//!
//! `profiles.json` is generated by `compat/create_provider_fixture.py`. A profile names the
//! default endpoint, the environment variables that may hold its key or an endpoint override,
//! and whether it speaks Chat Completions or Responses.

use std::sync::LazyLock;

use serde::Deserialize;

#[derive(Debug, Deserialize)]
pub struct Profile {
    pub name: String,
    pub aliases: Vec<String>,
    pub api_mode: String,
    pub base_url: String,
    pub key_envs: Vec<String>,
    pub base_url_envs: Vec<String>,
}

impl Profile {
    pub fn uses_responses(&self) -> bool {
        self.api_mode == "codex_responses"
    }
}

static PROFILES: LazyLock<Vec<Profile>> = LazyLock::new(|| {
    serde_json::from_str(include_str!("profiles.json")).expect("valid profiles.json")
});

fn normalise(name: &str) -> String {
    name.trim().to_ascii_lowercase().replace('_', "-")
}

/// The profile named `name` or listed under one of its aliases.
pub fn lookup(name: &str) -> Option<&'static Profile> {
    let wanted = normalise(name);
    PROFILES.iter().find(|profile| {
        profile.name == wanted
            || profile
                .aliases
                .iter()
                .any(|alias| normalise(alias) == wanted)
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn finds_profiles_by_name_and_alias() {
        assert_eq!(lookup("xai").unwrap().base_url, "https://api.x.ai/v1");
        assert!(lookup("xai").unwrap().uses_responses());
        assert_eq!(lookup("Grok").unwrap().name, "xai");
        assert_eq!(lookup("hf").unwrap().key_envs, ["HF_TOKEN"]);
        assert_eq!(lookup("gmi_cloud").unwrap().base_url_envs, ["GMI_BASE_URL"]);
        assert!(
            lookup("deepseek").is_none(),
            "profiles with request quirks are not listed"
        );
        assert!(lookup("nope").is_none());
    }
}
